-- Apply to an EMPTY schema. Data from official pages, 2026-10-25.
BEGIN;
SELECT setval(pg_get_serial_sequence('academic_units','id'), coalesce(max(id),1), count(*)>0) FROM academic_units;
SELECT setval(pg_get_serial_sequence('programs','id'), coalesce(max(id),1), count(*)>0) FROM programs;
SELECT setval(pg_get_serial_sequence('curricula','id'), coalesce(max(id),1), count(*)>0) FROM curricula;
SELECT setval(pg_get_serial_sequence('courses','id'), coalesce(max(id),1), count(*)>0) FROM courses;
SELECT setval(pg_get_serial_sequence('course_revisions','id'), coalesce(max(id),1), count(*)>0) FROM course_revisions;
SELECT setval(pg_get_serial_sequence('elective_groups','id'), coalesce(max(id),1), count(*)>0) FROM elective_groups;
SELECT setval(pg_get_serial_sequence('curriculum_courses','id'), coalesce(max(id),1), count(*)>0) FROM curriculum_courses;
COMMIT;
